&lt;div class="msgHead"&gt;
&lt;h1&gt;
&lt;span class="subject"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=subject:%22%5C%5Bblink%5C-dev%5C%5D+Intent+to+Prototype%5C%3A+Prefetch+activation+beacon%22&amp;o=newest" rel="nofollow"&gt;&lt;span itemprop="name"&gt;[blink-dev] Intent to Prototype: Prefetch activation beacon&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;
&lt;/h1&gt;
&lt;p class="darkgray font13"&gt;
&lt;span class="sender pipe"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=from:%22%27Jiacheng+Guo%27+via+blink%5C-dev%22" rel="nofollow"&gt;&lt;span itemprop="author" itemscope itemtype="http://schema.org/Person"&gt;&lt;span itemprop="name"&gt;'Jiacheng Guo' via blink-dev&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;
&lt;span class="date"&gt;&lt;a href="/search?l=blink-dev@chromium.org&amp;q=date:20260513" rel="nofollow"&gt;Wed, 13 May 2026 00:34:03 -0700&lt;/a&gt;&lt;/span&gt;
&lt;/p&gt;
